import json,hashlib,os
ROOT=Path('/home/kestrel/projects/luma-editor');BASE=Path('/tmp/canoli-wet-direct-only-baseline');STAGE=Path('/tmp/canoli-cursor-stage');sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();old=json.loads((BASE/'source-manifest.json').read_text());prior=json.loads((BASE/'prior-evidence.json').read_text());assert not STAGE.exists();assert all(sha(ROOT/n)==h for n,h in old.items());assert all(sha(ROOT/n)==h for n,h in prior.items());STAGE.mkdir()
for n,h in old.items():
 p=STAGE/n;p.parent.mkdir(parents=True,exist_ok=True);os.link(BASE/n,p)
(STAGE/'node_modules').symlink_to(ROOT/'node_modules',target_is_directory=True)
p=STAGE/'vite.config.ts';p.unlink();p.write_text("import {defineConfig} from 'vite';\nexport default defineConfig({cacheDir:'/tmp/canoli-cursor-stage/.vite-cache',optimizeDeps:{include:['exifr']},worker:{format:'es'},server:{port:5238,strictPort:true,fs:{allow:['/tmp/canoli-cursor-stage','/home/kestrel/projects/luma-editor/node_modules']}}});\n")
p=STAGE/'src/ui/CanvasCursor.tsx';text=p.read_text();needle='    refresh.current = () => { if (frame !== null) cancelAnimationFrame(frame); frame = null; if (last) draw(); else if (!latest.current.enabled) hide(); };';assert text.count(needle)==1;text=text.replace(needle,"""    refresh.current = () => {
      // React commits may update several cursor inputs together. Reuse the
      // pointer frame so those commits never force repeated viewport layout.
      // Disabling still restores the system pointer synchronously.
      if (!latest.current.enabled) { hide(); return; }
      if (last && frame === null) frame = requestAnimationFrame(draw);
    };""");p.unlink();p.write_text(text)
p=STAGE/'tests/canvas-cursors.e2e.ts';text=p.read_text();p.unlink();p.write_text(text)
assert all(sha(BASE/n)==h for n,h in old.items());print('Independent cursor-only candidate created; direct delivery and paired image preparation excluded; all30artifacts preserved.')

