releases={'baseline':{'root':baseline,'release':{name.removeprefix('dist/'):digest for name,digest in json.load(open(baseline/'release-manifest.json')).items()},'port':5234},'candidate':{'root':stage,'release':epoch['release'],'port':5240}}
