import {readFile,writeFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import assert from 'node:assert/strict';
import {readProject} from '/home/kestrel/projects/luma-editor/src/core/project.ts';
const root='/tmp/canoli-cursor-adapters-controlled-2';
const report=JSON.parse(await readFile(root+'/comparison.json','utf8')),results=[];
for(const run of report.runs)for(const entry of run.report.reports){
 const projects={};
 for(const kind of ['before','after','undo']){
  const path=entry.projects[kind].path,bytes=await readFile(path);
  assert.equal(createHash('sha256').update(bytes).digest('hex'),entry.projects[kind].sha256);
  projects[kind]=await readProject(new Blob([new Uint8Array(bytes)]));
 }
 assert.deepEqual(projects.before.document,projects.undo.document);
 const expected=structuredClone(projects.before.document),actual=projects.after.document;
 assert.equal(actual.schemaVersion,34);assert.equal(actual.width,512);assert.equal(actual.height,128);
 const target=actual.children.find(layer=>layer.name==='Measured wet stroke'),old=expected.children.find(layer=>layer.name==='Measured wet stroke');
 assert.ok(target&&old);
 const mask=entry.fixture.target==='mask'?'mask':'filterMask';
 const operation=entry.fixture.target==='layer'?target.strokes.at(-1):target[mask].strokes.at(-1).stroke;
 assert.equal(operation.kind,'wet');
 assert.deepEqual(operation.brush.points.map(p=>[p.x,p.y]),[[36,64],...Array.from({length:20},(_,i)=>[48+i*12,64])]);
 if(entry.fixture.target==='layer')old.strokes.push(operation);else old[mask].strokes.push({mode:'wet',stroke:operation});
 assert.deepEqual(actual,expected);
 results.push({round:run.round,release:run.release,fixture:entry.fixture.id,onlyOneExpectedNativeOperation:true,all21PointCoordinatesExact:true,oneUndoExactModel:true,projectSha256:entry.projects});
}
assert.equal(results.length,36);
const path=root+'/independent-project-audit.json';
try{assert.deepEqual(JSON.parse(await readFile(path,'utf8')),results);}
catch(error){if(error.code!=='ENOENT')throw error;await writeFile(path,JSON.stringify(results,null,2)+'\n',{flag:'wx'});}
console.log('108project containers:36exact undo pairs, one intended native operation, all21x/y coordinates verified.');

